<?php namespace Workspace; $pid=(int)$project['id']; ?>
<p><a href="<?= h(url('project',['id'=>$pid])) ?>">← <?= h($project['title']) ?></a> · <a href="<?= h(url('infrastructure',['project'=>$pid])) ?>">Инфраструктура</a> · <a href="<?= h(url('releases',['project'=>$pid])) ?>">Выпуски</a></p>
<section class="panel"><h2>Новое развёртывание</h2><p>Только подтверждённый релиз и сайт, назначенный вам в матрице site.deploy. Окно в UTC. Запрос выполняет доверенный локальный worker на целевом хосте, не HTTP-процесс.</p>
<?php if($deploymentSites&&$deploymentReleases): ?><form method="post" class="formgrid"><?php formFields('deploy.create') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><label>Сайт и окружение<select name="site_id" required><?php selectOptions($deploymentSites) ?></select></label><label>Подтверждённый выпуск<select name="release_id" required><?php selectOptions($deploymentReleases) ?></select></label><label>Начало (UTC)<input type="datetime-local" name="window_start" required value="<?= h(gmdate('Y-m-d\TH:i')) ?>"></label><label>Окончание (UTC)<input type="datetime-local" name="window_end" required value="<?= h(gmdate('Y-m-d\TH:i',time()+3600)) ?>"></label><button class="primary">Запланировать (MFA)</button></form><?php else: ?><p>Нет доступных сайтов с назначением или подтверждённых выпусков.</p><?php endif ?></section>
<section class="panel"><h2>История развёртываний</h2><p>Последние 100 заданий. При неопределённом результате новые деплои на сайт блокируются до восстановления.</p><?php foreach($deployments as $d): $res=$d['result']?json_decode($d['result'],true):[]; ?>
<div class="inset"><h3>#<?= (int)$d['id'] ?> · <?= h($d['tag']) ?> → <?= h($d['site_name']) ?> · <?= h($d['state']) ?></h3><p><?= h($d['provider']) ?> · <?= h($d['actor_name']) ?> · SHA <?= h($d['commit_sha']) ?></p><p><a href="<?= h(url('release_trace',['project'=>$pid,'id'=>$d['release_id'],'job'=>$d['id']])) ?>">След выпуска и эксплуатации (MFA)</a></p><p>Окно <?= h(gmdate('Y-m-d H:i',(int)$d['window_start'])) ?> — <?= h(gmdate('Y-m-d H:i',(int)$d['window_end'])) ?> UTC</p><p>Начало <?= $d['started_at']?h(gmdate('Y-m-d H:i:s',(int)$d['started_at'])):'—' ?> · завершение <?= $d['finished_at']?h(gmdate('Y-m-d H:i:s',(int)$d['finished_at'])):'—' ?> UTC</p><?php if($res): ?><p><?= h($res['message']??'') ?></p><p>SHA до: <?= h($res['before']??'—') ?> · после: <?= h($res['after']??'—') ?></p><?php endif ?>
<?php if($d['state']==='queued'&&$deploymentOperate&&($deploymentUser['role']==='owner'||(int)$deploymentUser['id']===(int)$d['actor_id'])): ?><form method="post"><?php formFields('deploy.cancel') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= (int)$d['id'] ?>"><button class="secondary">Отменить (MFA)</button></form><?php endif ?></div><?php endforeach ?><?php if(!$deployments): ?><p>Нет заданий.</p><?php endif ?></section>
